 sahsiyetler=[
  P('Urve b. ez-Zübeyr', 'عروة بن الزبير', '94/713', 'siyer', 'tâbiî, ilk megāzî râvisi', 'Hz. Zübeyr ile Hz. Esmâ’nın oğlu, Hz. Âişe’nin yeğenidir. Medine’nin yedi fakihinden biridir. Halife Abdülmelik’e yazdığı, Peygamber’in hayatına dair mektuplar siyer yazıcılığının ilk örnekleri sayılır.', ['Megāzî rivayetleri (Taberî ve İbn İshâk’ta)'], 'Ona nispet edilen bağımsız bir “Megāzî” kitabı günümüze ulaşmamıştır; rivayetleri sonraki eserlerde parça parça yaşar.'),
  P('Ebân b. Osman', 'أبان بن عثمان', '105/723 dolayı', 'siyer', 'tâbiî, siyer râvisi', 'Hz. Osman’ın oğludur; Medine valiliği yaptı. Megāzîye dair bir sahîfe yazdığı nakledilir.', ['Megāzî sahîfesi (kayıp)']),
  P('Vehb b. Münebbih', 'وهب بن منبه', '110/728 dolayı', 'siyer', 'tâbiî, kıssa ve megāzî râvisi', 'Yemenli tâbiîdir; Ehl-i kitap kaynaklarını iyi bilirdi. Peygamberler kıssalarına dair geniş rivayetleri vardır; isrâiliyyâtın önemli kaynaklarından sayılır.', ['Kitâbü’t-Tîcân (İbn Hişâm rivayetiyle)', 'Megāzî parçası (Heidelberg papirüsü)']),
  P('İbn Şihâb ez-Zührî', 'ابن شهاب الزهري', '124/742', 'siyer', 'muhaddis ve megāzî âlimi', 'Hadisi ilk resmî olarak toplayanlardan, Emevî sarayına yakın Medineli âlimdir. Siyer rivayetlerini isnadlarıyla birleştirerek ilk kronolojik çerçeveyi kurmuştur; İbn İshâk ve Mûsâ b. Ukbe onun talebesidir.', ['Megāzî rivayetleri']),
  P('Mûsâ b. Ukbe', 'موسى بن عقبة', '141/758', 'siyer', 'megāzî müellifi', 'Zübeyr ailesinin mevlâsıdır. Megāzî’si güvenilirliği sebebiyle İmam Mâlik tarafından övülmüştür; eserden parçalar günümüze ulaşmıştır.', ['el-Megāzî (parçaları)']),
  P('İbn İshâk', 'محمد بن إسحاق', '151/768', 'siyer', 'siyer imamı', 'Medineli, sonra Irak’a göç eden siyer âlimidir. Abbâsî halifesi Mansûr için yaratılıştan başlayan büyük bir siyer yazdı. Eser kendi hâliyle kaybolmuş, İbn Hişâm, Yûnus b. Bükeyr ve diğer râvilerin rivayetleriyle bize ulaşmıştır. Muhaddisler hadiste görüş ayrılığına düşse de siyerde imam saymışlardır.', ['es-Sîre / el-Mübtedâ ve’l-meb‘as ve’l-megāzî'], 'Bugün “İbn İshâk’ın Sîre’si” diye okunan metin aslında İbn Hişâm’ın ayıklayıp kısalttığı rivayettir.'),
  P('Ebû Mihnef', 'أبو مخنف لوط بن يحيى', '157/774', 'siyer', 'ahbârî (Irak)', 'Kûfeli haber derleyicisidir. Ridde, Cemel, Sıffîn ve Kerbelâ gibi olaylara dair monografileri Taberî’ye geniş kaynak olmuştur. Irak ve Ehl-i beyt eğilimi taşıdığı kabul edilir.', ['Maktelü’l-Hüseyn (Taberî’deki rivayetler)'], 'Bugün “Maktelü Ebî Mihnef” adıyla basılan metin sonraki dönem ilaveleri içerir; asıl rivayetleri Taberî’deki parçalardır.'),
  P('Seyf b. Ömer', 'سيف بن عمر', '180/796 dolayı', 'siyer', 'ahbârî', 'Ridde ve fütûhâta dair eserleri Taberî’de geniş yer tutar. Muhaddisler onu hadiste zayıf, hatta metruk saymıştır; bu yüzden rivayetleri dikkatle kullanılır.', ['Kitâbü’r-Ridde ve’l-fütûh', 'el-Cemel']),
  P('Vâkıdî', 'محمد بن عمر الواقدي', '207/823', 'siyer', 'megāzî ve tarih âlimi', 'Medineli, sonra Bağdat kadısı olan büyük tarihçidir. Gazvelerin yerlerini gezip tarihlerini tespit etmesiyle tanınır. Muhaddisler rivayetini zayıf saysa da megāzîde bilgisi vazgeçilmezdir.', ['Kitâbü’l-Megāzî', 'Kitâbü’r-Ridde (parçalar)'], 'Ona nispet edilen “Fütûhu’ş-Şâm” sonraki asırlarda yazılmış halk anlatısıdır; Vâkıdî’ye ait değildir.'),
  P('İbn Hişâm', 'عبد الملك بن هشام', '218/833', 'siyer', 'siyer ve nesep âlimi', 'Basra asıllı, Mısır’da yaşamış dil ve nesep âlimidir. İbn İshâk’ın Sîre’sini Ziyâd el-Bekkâî rivayetiyle alıp ayıkladı, şiirleri ve neseb bilgilerini düzeltti.', ['es-Sîretü’n-nebeviyye', 'Kitâbü’t-Tîcân']),
  P('Hişâm b. el-Kelbî', 'هشام بن الكلبي', '204/819 dolayı', 'siyer', 'nesep ve câhiliye âlimi', 'Arap soyları ve câhiliye kültürünün en büyük râvisidir. Muhaddisler ona güvenmemiş, ancak nesep ve câhiliye tarihinde eserleri temel kaynak olmuştur.', ['Cemheretü’n-neseb', 'Kitâbü’l-Esnâm']),
  P('İbn Sa‘d', 'محمد بن سعد', '230/845', 'klasik', 'tabakât müellifi', '“Kâtibü’l-Vâkıdî” diye bilinir. Siyer ve megāzîye yer veren ilk tabakât müellifidir; sahâbe, tâbiûn ve sonrakilerin biyografilerini şehir ve nesil esasına göre derlemiştir.', ['et-Tabakātü’l-kübrâ']),
  P('Halîfe b. Hayyât', 'خليفة بن خياط', '240/854', 'klasik', 'tarihçi ve muhaddis', 'Basralı muhaddistir. Günümüze ulaşan en eski yıllık İslâm tarihi onundur.', ['et-Târîh', 'et-Tabakāt']),
  P('Belâzürî', 'أحمد بن يحيى البلاذري', '279/892', 'klasik', 'tarihçi', 'Abbâsî sarayında nedimlik yapmış tarihçidir. Fetihleri bölge bölge anlatan ve idarî-malî bilgi veren eseri ile soy esasına göre yazılmış dev tarihi temel kaynaklardır.', ['Fütûhu’l-büldân', 'Ensâbü’l-eşrâf']),
  P('Ya‘kūbî', 'اليعقوبي', '292/905 sonrası', 'klasik', 'tarihçi ve coğrafyacı', 'Ermenistan ve Horasan’da bulunmuş, çok gezmiş tarihçidir. Eseri İslâm öncesi milletlerle başlar; Ehl-i beyt eğilimi taşır.', ['Târîhu’l-Ya‘kūbî', 'Kitâbü’l-Büldân']),
  P('Dîneverî', 'أبو حنيفة الدينوري', '282/895 dolayı', 'klasik', 'tarihçi ve âlim', 'İran geleneğine de yer veren anlatı tarzı tarihiyle bilinir; botanik ve dil âlimidir.', ['el-Ahbârü’t-tıvâl', 'Kitâbü’n-Nebât']),
  P('Taberî', 'ابن جرير الطبري', '310/923', 'klasik', 'müfessir, tarihçi, fakih', 'Âmul’de doğdu, Bağdat’ta yaşadı. Tefsirde olduğu gibi tarihte de rivayetleri isnadlarıyla toplayan yöntemi izledi; yaratılıştan 302/915’e kadar yıllık bir tarih yazdı. Mukaddimesinde haberleri olduğu gibi naklettiğini, sorumluluğun râvilerde olduğunu söyler.', ['Târîhu’r-rusül ve’l-mülûk', 'Câmiu’l-beyân']),
  P('Mes‘ûdî', 'المسعودي', '345/956', 'klasik', 'tarihçi ve seyyah', 'Hindistan’dan Doğu Afrika’ya geniş seyahatler yapmış, coğrafya ve kültürü tarihe katmıştır. Konulu tarih yazıcılığının önde gelen ismidir.', ['Murûcü’z-zeheb', 'et-Tenbîh ve’l-işrâf']),
  P('Miskeveyh', 'مسكويه', '421/1030', 'klasik', 'tarihçi ve ahlâk filozofu', 'Büveyhî kâtibidir. Tarihten ibret ve tecrübe çıkarmayı amaçlayan eseri, olayları sebep-sonuç ilişkisiyle anlatır.', ['Tecâribü’l-ümem', 'Tehzîbü’l-ahlâk']),
  P('Hatîb el-Bağdâdî', 'الخطيب البغدادي', '463/1071', 'klasik', 'muhaddis ve tarihçi', 'Şehir tarihi türünün en büyük örneğini yazmıştır: Bağdat’ın topografyası ve orada yaşamış binlerce kişinin biyografisi.', ['Târîhu Bağdâd']),
  P('İbn Asâkir', 'ابن عساكر', '571/1176', 'orta', 'muhaddis ve tarihçi', 'Dımaşklı muhaddistir; Dımaşk’a gelmiş herkesin biyografisini içeren seksen ciltlik eseri İslâm’ın en büyük şehir tarihidir.', ['Târîhu medîneti Dımaşk']),
  P('İbnü’l-Cevzî', 'ابن الجوزي', '597/1201', 'orta', 'vâiz, muhaddis, tarihçi', 'Bağdatlı Hanbelî âlimdir. Yıllık olaylarla vefeyâtı birleştiren tarih türünün öncüsüdür.', ['el-Muntazam', 'Sıfatü’s-safve']),
  P('İbnü’l-Esîr', 'عز الدين ابن الأثير', '630/1233', 'orta', 'tarihçi', 'Musullu tarihçidir. Taberî’yi kısaltıp kendi zamanına kadar sürdürdüğü eseri, Haçlılar ve Moğol istilasının çağdaş tanıklığıdır.', ['el-Kâmil fi’t-târîh', 'Üsdü’l-gābe']),
  P('İbn Hallikân', 'ابن خلكان', '681/1282', 'orta', 'kadı ve biyografi yazarı', 'Erbilli kadıdır. Ünlü kişilerin vefat tarihlerine göre düzenlenmiş biyografi sözlüğü, vefeyât türünün en çok okunan eseridir.', ['Vefeyâtü’l-a‘yân']),
  P('Zehebî', 'الذهبي', '748/1348', 'orta', 'muhaddis ve tarihçi', 'Dımaşklı muhaddistir; hadis tenkidini tarih ve biyografiye uygulamıştır.', ['Târîhu’l-İslâm', 'Siyerü a‘lâmi’n-nübelâ', 'Tezkiretü’l-huffâz']),
  P('İbn Kesîr', 'ابن كثير', '774/1373', 'orta', 'müfessir ve tarihçi', 'Dımaşklı Şâfiî âlimdir. Tarihi, siyer kısmında hadis tenkidi yapmasıyla değerlidir.', ['el-Bidâye ve’n-nihâye', 'Tefsîrü’l-Kur’âni’l-azîm']),
  P('İbn Haldûn', 'ابن خلدون', '808/1406', 'orta', 'tarihçi ve düşünür', 'Tunuslu devlet adamı ve kadıdır. Mukaddime’de haber tenkidinin ölçütlerini, devletlerin doğuş ve çöküşünü “asabiyet” kavramıyla açıklayan umrân ilmini kurdu.', ['Mukaddime', 'Kitâbü’l-İber']),
  P('Makrîzî', 'المقريزي', '845/1442', 'orta', 'tarihçi', 'Kahireli tarihçidir; Mısır’ın topografyası, kurumları ve hanedanları üzerine temel eserler yazdı.', ['el-Mevâiz ve’l-i‘tibâr (el-Hıtat)', 'es-Sülûk']),
  P('İbn Hacer el-Askalânî', 'ابن حجر العسقلاني', '852/1449', 'orta', 'muhaddis', 'Sahâbe biyografilerinin en kapsamlı derlemesini yapmıştır.', ['el-İsâbe fî temyîzi’s-sahâbe', 'ed-Dürerü’l-kâmine']),
  P('Sehâvî', 'السخاوي', '902/1497', 'orta', 'muhaddis ve tarihçi', 'İbn Hacer’in talebesidir. Tarih ilmini savunan ve yöntemini anlatan risâlesi ile IX. asır biyografileri meşhurdur.', ['el-İ‘lân bi’t-tevbîh', 'ed-Dav’ü’l-lâmi‘']),
  P('Süyûtî', 'السيوطي', '911/1505', 'orta', 'çok yönlü âlim', 'Tarih alanında halifeler tarihi ve tabakât eserleri yazmıştır.', ['Târîhu’l-hulefâ', 'Hüsnü’l-muhâdara']),
  P('Âşıkpaşazâde', 'عاشق پاشازاده', '889/1484 sonrası', 'osmanli', 'Osmanlı tarihçisi', 'Osmanlı’nın kuruluşunu anlatan ilk kroniklerden birinin müellifidir; halk dilini ve sözlü rivayetleri kullanır.', ['Tevârîh-i Âl-i Osmân']),
  P('Kemalpaşazâde', 'ابن كمال', '940/1534', 'osmanli', 'şeyhülislâm ve tarihçi', 'II. Bayezid’in emriyle Osmanlı tarihini sanatlı nesirle yazdı.', ['Tevârîh-i Âl-i Osmân']),
  P('Taşköprizâde', 'طاشكبري زاده', '968/1561', 'osmanli', 'âlim ve biyografi yazarı', 'Osmanlı âlim ve şeyhlerinin biyografilerini ve ilimlerin tasnifini yazdı.', ['eş-Şekāiku’n-Nu‘mâniyye', 'Miftâhu’s-saâde']),
  P('Kâtib Çelebi', 'كاتب چلبي', '1067/1657', 'osmanli', 'bibliyograf ve tarihçi', 'Osmanlı’nın en önemli bibliyografı; ilimlerin ve kitapların ansiklopedisini, takvimli bir dünya tarihi ve coğrafya eserleri yazdı.', ['Keşfü’z-zunûn', 'Takvîmü’t-tevârîh', 'Cihannümâ']),
  P('Naîmâ', 'نعيما', '1128/1716', 'osmanli', 'vakanüvis', 'İlk resmî vakanüvis kabul edilir; İbn Haldûn’un fikirlerini Osmanlı tarihine uyguladı.', ['Târih-i Naîmâ']),
  P('Ahmed Cevdet Paşa', 'أحمد جودت باشا', '1312/1895', 'osmanli', 'tarihçi ve devlet adamı', 'Mecelle’yi hazırlayan heyetin başkanı; Osmanlı tarihine dair eserinin yanında Peygamberler ve Hulefâ tarihini de yazdı.', ['Târih-i Cevdet', 'Kısas-ı Enbiyâ ve Tevârîh-i Hulefâ']),
  P('Muhammed Hamîdullah', 'محمد حميد الله', '1423/2002', 'modern', 'siyer ve İslâm hukuku âlimi', 'Haydarâbâd doğumlu, ömrünün çoğunu Paris’te geçirmiş âlimdir. Peygamber dönemine ait vesikaları ve mektupları toplamış; Türkiye’de uzun yıllar ders vermiştir.', ['İslâm Peygamberi', 'el-Vesâiku’s-siyâsiyye', 'İslâm Tarihine Giriş']),
  P('Mustafa Fayda', '—', 'çağdaş', 'modern', 'İslâm tarihçisi', 'Marmara İlahiyat’ta yetişmiş, Hulefâ-i Râşidîn dönemi ve siyer kaynakları üzerine Türkiye’nin önde gelen uzmanlarındandır; TDV İslâm Ansiklopedisi’nin siyer maddelerini yazmıştır.', ['Hulefâ-yi Râşidîn Devri', 'Allah’ın Kılıcı Hâlid b. Velîd']),
  P('Neşet Çağatay', '—', '1420/1999', 'modern', 'İslâm tarihçisi', 'Ankara İlahiyat’ta İslâm tarihi kürsüsünün kurucularındandır; Ahîlik ve İslâm öncesi Arap tarihi üzerine çalışmıştır.', ['İslâm’dan Önce Arap Tarihi ve Câhiliye Çağı', 'Bir Türk Kurumu Olan Ahilik']),
  P('Hz. Ebû Bekir', 'أبو بكر الصديق', '13/634', 'hukumdar', 'ilk halife', 'Peygamber’in en yakın arkadaşı ve ilk halifesidir. Ridde savaşlarıyla birliği korudu, Kur’an’ı mushaf hâlinde topladı ve Irak ile Suriye fetihlerini başlattı.', []),
  P('Hz. Ömer', 'عمر بن الخطاب', '23/644', 'hukumdar', 'ikinci halife', 'Fetihlerin büyük kısmı onun döneminde gerçekleşti. Hicrî takvimi başlattı, divan teşkilatını kurdu, fethedilen toprakların idaresini düzenledi.', []),
  P('Hz. Osman', 'عثمان بن عفان', '35/656', 'hukumdar', 'üçüncü halife', 'Mushafı çoğaltıp merkezlere gönderdi. Döneminin sonundaki iç karışıklıklar şehadetiyle sonuçlandı ve “fitne” dönemini başlattı.', []),
  P('Hz. Ali', 'علي بن أبي طالب', '40/661', 'hukumdar', 'dördüncü halife', 'Cemel ve Sıffîn savaşları, tahkim ve Hâricîlerin doğuşu onun hilâfeti döneminde oldu; Kûfe’de bir Hâricî tarafından şehit edildi.', []),
  P('Muâviye b. Ebû Süfyân', 'معاوية بن أبي سفيان', '60/680', 'hukumdar', 'Emevî devletinin kurucusu', 'Uzun yıllar Şam valiliği yaptı; 41/661’de halife oldu ve hilâfeti babadan oğula geçen bir saltanata dönüştürdü. Deniz donanmasını kurdu.', []),
  P('Ömer b. Abdülazîz', 'عمر بن عبد العزيز', '101/720', 'hukumdar', 'Emevî halifesi', 'Adaleti ve zühdüyle “beşinci râşid halife” diye anılır. Hadislerin toplanmasını resmî olarak emrettiği nakledilir.', []),
  P('Hârûnürreşîd', 'هارون الرشيد', '193/809', 'hukumdar', 'Abbâsî halifesi', 'Abbâsî gücünün zirvesini temsil eder; Bağdat ilim ve kültür merkezi hâline geldi.', []),
  P('Selâhaddîn-i Eyyûbî', 'صلاح الدين الأيوبي', '589/1193', 'hukumdar', 'Eyyûbî sultanı', 'Fâtımî hilâfetine son verdi, Hıttîn’de Haçlıları yenip Kudüs’ü 583/1187’de geri aldı.', []),
  P('Fâtih Sultan Mehmed', 'محمد الفاتح', '886/1481', 'hukumdar', 'Osmanlı padişahı', '857/1453’te İstanbul’u fethetti; Sahn-ı Semân medreselerini kurdu.', [])],
